#!/usr/bin/env bash
# Creates .env for the local Compose stack with random passwords and secrets.
# .env is git-ignored: it stays on your computer. Each developer generates their own.
#
# Usage: scripts/dev-env.sh

set -euo pipefail
cd "$(dirname "$0")/.."

if [[ -e .env ]]; then
  echo ".env already exists. To start over: docker compose down -v && rm .env (deletes local data)"
  exit 1
fi

# 16 random bytes → 32 hex characters (Kratos's cipher secret must be exactly 32)
random_hex() { openssl rand -hex 16; }

cat > .env <<EOF
# Generated by scripts/dev-env.sh on $(date +%F). LOCAL DEVELOPMENT ONLY. Never commit.
POSTGRES_PASSWORD=$(random_hex)
KRATOS_DB_PASSWORD=$(random_hex)
TRACKS_DB_PASSWORD=$(random_hex)
KRATOS_COOKIE_SECRET=$(random_hex)
KRATOS_CIPHER_SECRET=$(random_hex)
RUSTFS_ACCESS_KEY=aret-dev
RUSTFS_SECRET_KEY=$(random_hex)
EOF
chmod 600 .env
echo "Created .env (readable only by you). Next: docker compose up -d"
